    <a class="brand" href="index.php"><?php require_once __DIR__ . '/../backend/brand.php'; echo tms_brand_mark_html('40'); ?></a>
    <h2>Welcome back. Your next trip is waiting.</h2>
    <p>Pick up where you left off: your plans, tickets and saved places.</p>
    <div class="tms-scene" aria-hidden="true"><i class="s-cloud"></i><i class="s-far"></i><i class="s-near"></i><i class="s-palm"></i><i class="s-wave"></i><i class="s-wave w2"></i><i class="s-plane"></i></div>
  </aside>

  <section class="tms-auth-main">
    <div class="tms-auth-card">
      <?php if ($showingTwoFactorPrompt): ?>
      <h1>Almost there</h1>
      <p class="lead">Enter the 6-digit code from your authenticator app, or one of your recovery codes.</p>
      <?php else: ?>
      <h1>Sign in</h1>
      <p class="lead">Good to see you again.</p>
      <?php endif; ?>

      <?php if ($error): ?>
        <div class="tms-alert bad" id="authErr" role="alert"><i class="fa fa-exclamation-circle" aria-hidden="true"></i> <span><?= htmlspecialchars($error) ?></span></div>
      <?php endif; ?>
      <?php $errAttr = $error ? ' aria-invalid="true" aria-describedby="authErr"' : ''; ?>

      <?php if ($showingTwoFactorPrompt): ?>
      <!-- The password was already correct: this second form only appears after that (u2fa_pending set server-side). -->
      <form method="POST" action="login.php" id="twoFactorForm">
        <?php tms_csrf_field(); ?>
        <div class="tms-field">
          <label for="totpCodeField">Authentication code</label>
          <div class="tms-input">
            <i class="fa fa-key fi" aria-hidden="true"></i>
            <input type="text" name="totp_code" id="totpCodeField"
                   inputmode="text" maxlength="12" autocapitalize="characters" spellcheck="false"
                   placeholder="123456 or XXXXX-XXXXX" required autofocus autocomplete="one-time-code"<?= $errAttr ?>>
          </div>
        </div>
        <button type="submit" name="btn-verify-2fa" class="tms-btn-primary">
          <i class="fa fa-check" aria-hidden="true"></i> Verify &amp; sign in
        </button>
      </form>
      <p class="alt"><a href="login.php?cancel_2fa=1"><i class="fa fa-arrow-left" aria-hidden="true"></i> Back to sign in</a></p>
      <?php else: ?>
      <form method="POST" action="login.php" id="loginForm">
        <?php tms_csrf_field(); ?>

        <div class="tms-field">
          <label for="loginEmailField">Email</label>
          <div class="tms-input">
            <i class="fa fa-envelope fi" aria-hidden="true"></i>
            <input type="email" name="EmailId" id="loginEmailField"
                   placeholder="you@example.com" autocomplete="email"
                   value="<?= htmlspecialchars($_POST['EmailId'] ?? '', ENT_QUOTES) ?>"
                   required autofocus maxlength="100"<?= $errAttr ?>>
          </div>
        </div>

        <div class="tms-field">
          <label for="passField">Password</label>
          <div class="tms-input has-eye">
            <i class="fa fa-lock fi" aria-hidden="true"></i>
            <input type="password" name="Password" id="passField"
                   placeholder="Your password" autocomplete="current-password"
                   required maxlength="100"<?= $errAttr ?>>
            <button type="button" class="eye-btn" onclick="togglePass()" id="eyeToggleBtn" aria-label="Show password">
              <i class="fa fa-eye" id="eyeIcon" aria-hidden="true"></i>
            </button>
          </div>
          <p class="tms-hint" style="text-align:right;margin:8px 0 0;"><a class="link" href="forgot-password.php">Forgot password?</a></p>
        </div>

        <button type="submit" class="tms-btn-primary" id="loginBtn">
          <i class="fa fa-sign-in" aria-hidden="true"></i> Sign in
        </button>
      </form>

      <div class="or">or</div>
      <?php echo GoogleAuth::button((string)($_GET['redirect'] ?? ($_SESSION['post_login_redirect'] ?? ''))); ?>

      <p class="alt">New here? <a href="register.php">Create an account</a></p>
      <?php endif; ?>
    </div>
  </section>
</main>

<script>
function togglePass() {
  var f = document.getElementById('passField');
  var i = document.getElementById('eyeIcon');
  var btn = document.getElementById('eyeToggleBtn');
  f.type = f.type === 'password' ? 'text' : 'password';
  i.className = f.type === 'password' ? 'fa fa-eye' : 'fa fa-eye-slash';
  // aria-label tracks what the button does next (icon-only button has no other name).
  if (btn) btn.setAttribute('aria-label', f.type === 'password' ? 'Show password' : 'Hide password');
}
// The 2FA step has no #loginForm/#loginBtn, so guard instead of assuming the password form is in the DOM.
var tmsLoginForm = document.getElementById('loginForm');
if (tmsLoginForm) {
  tmsLoginForm.addEventListener('submit', function() {
    var btn = document.getElementById('loginBtn');
    btn.disabled = true;
    btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Signing in…';
  });
}
</script>

